# %% ../nbs/05_cells.ipynb #104800db
_prompt_state:'_RunState|None' = None  # the one Prompt cell currently streaming a reply, if any -- parallel to _run_state (code), not shared with it: a code cell and a prompt reply use different resources and can run at the same time.

def _run_prompt_bg(context:str, model:str, tools:list, think:str|None, images:list|None, state:_RunState) -> None:
    "Runs in a background thread: drives llms.stream_llm_reply() (which owns the actual model-calling strategy, including how tools are exposed and reasoning effort is applied -- see there) into state.buffer/state.blocks. This function's only job is the background-thread/UI-state plumbing shared with code-cell streaming; it has no LLM-specific logic of its own."
    gen = stream_llm_reply(context, model, tools, think, images, nb.keep_alive_min, nb.num_ctx)
    try:
        for item in gen:
            if item[0] == 'final':
                _, content, details = item
                state.blocks = (content, details)
            else:
                _, delta = item
                state.buffer.append(delta)
    except KeyboardInterrupt:
        state.blocks = (''.join(state.buffer) + '\n\n*(interrupted)*', None)
    except Exception as e:
        state.blocks = (f'(error calling {model}: {e})', None)
    finally:
        # Closing the generator is what stops the *model*, not merely our reading of it: GeneratorExit
        # unwinds through stream_llm_reply into litellm's streaming iterator and shuts the HTTP
        # response, and a dropped connection is the only way to cancel an Ollama generation -- it has
        # no cancel/abort endpoint (ollama-js's own abort() is an AbortController on the request, the
        # same thing). Left to garbage collection this happened only eventually, and until it did, an
        # interrupted prompt kept a model generating, and holding its RAM, with nobody listening.
        # Guarded because close() re-raises whatever the generator raises on the way out, and a second
        # interrupt landing here must not stop state.done being set -- the poller would spin forever.
        try: gen.close()
        except BaseException: pass
        state.done = True

# %% ../nbs/05_cells.ipynb #136e4da3
def _start_prompt_run(prompt_id:int) -> None:
    "Kick off the LLM call for `prompt_id`, streaming into _prompt_state -- in a background thread if a real model is configured, or resolved immediately via stub_reply() if not (no need for a thread when there's no real call to make). Uses nb.active_model() (standard or reasoning, per the brain-icon toggle) and, while reasoning is active, nb.reasoning_effort."
    global _prompt_state
    c = nb.get(prompt_id)
    state = _RunState(prompt_id)
    model = nb.active_model()
    if model:
        tools = get_tool_list(nb.tool_selection) + nb.tools
        _push_tools()  # keep the shell namespace in sync before the model can suggest calling any of these
        think = nb.reasoning_effort if nb.use_reasoning else None
        ctx = llm_context(nb, prompt_id)
        info = next((m for m in nb.models if m['id'] == model), None)
        # Attach referenced /boopimg/ images only when the active model says it can see them -- a
        # non-vision model just gets the markdown tags as text, same as before this feature existed.
        images = _context_images(ctx) if info and 'vision' in info.get('capabilities', []) else None
        state.thread = threading.Thread(target=_run_prompt_bg, args=(ctx, model, tools, think, images or None, state), daemon=True)
        _prompt_state = state
        state.thread.start()
    else:
        state.blocks = (stub_reply(nb, c.source), None)
        state.done = True
        _prompt_state = state

# %% ../nbs/05_cells.ipynb #17498997
def pending_prompt_cell(prompt_id:int, text:str='', oob_swap:str=None) -> FT:
    "Placeholder shown while a Prompt's LLM reply streams in the background: a pulsing 'Tricky...' indicator plus whatever text has accumulated so far, shown as plain preformatted text (not markdown-rendered -- mid-stream markdown is often invalid, e.g. an unclosed code fence; only the finished reply gets the full '.marked' treatment). hx-trigger=load polls run_prompt_poll() every 300ms until the reply is complete. `oob_swap`, if given, delivers this placeholder out-of-band (see _oob()) instead of being the response's main swap target."
    kw = {'hx_swap_oob': oob_swap} if oob_swap else {}
    parts = [Span('Assistant', cls='font-semibold text-sm'), Span(' Tricky...', cls='text-cyan-400 animate-pulse text-[15px] ml-1')]
    body = [Div(*parts, cls='flex items-center gap-1')]
    if text:
        body.append(Pre(text, cls='text-sm whitespace-pre-wrap mt-1 opacity-80'))
    return Div(*body, id=f'pending-{prompt_id}', cls='border-l-4 border-error pl-3 py-2 my-2 ml-8',
               hx_post=run_prompt_poll.to(id=prompt_id), hx_target=f'#pending-{prompt_id}',
               hx_swap='outerHTML', hx_trigger='load delay:300ms', **kw)

# %% ../nbs/05_cells.ipynb #4aa994f4
def _finalize_prompt_reply(prompt_id:int, content:str, details:str|None) -> Cell|None:
    "Write a completed LLM reply into the Prompt's paired Assistant cell, creating it if it doesn't already exist. Shared tail end of the old (now removed) run_prompt_cell(): the context-building half lives in _start_prompt_run(), this is the cell-writing half."
    c = nb.get(prompt_id)
    if not c or c.ctype != 'prompt': return None
    i = nb.index(c.id)
    nxt = nb.cells[i+1] if i+1 < len(nb.cells) else None
    if nxt is not None and nxt.ctype == 'assistant':
        nxt.source, nxt.model, nxt.details = content, nb.active_model(), details
        nxt.ts = datetime.now().strftime('%I:%M:%S %p')
    else:
        nxt = nb.insert_at(i+1, 'assistant', content, model=nb.active_model(), details=details)
    return nxt

# %% ../nbs/05_cells.ipynb #restartprompt1
def _restart_prompt_reply(c:Cell) -> tuple:
    "Kick off a fresh LLM run for prompt cell `c`, returning (re-rendered prompt cell, pending-reply placeholder) for a caller targeting '#cell-<c.id>' with outerHTML. Any existing reply is emptied in place -- same Cell, same DOM node id -- and the placeholder OOB-swaps into it, so a re-run replaces the old answer instead of growing a second one; only when there's no reply yet is a new node inserted after the prompt. Shared by both routes that re-answer a prompt (save_cell, after an edit; run_cell, from the play button), which is the point: the two used to differ, and the play button's swap target was additionally computed back when its toolbar was rendered (see cell_toolbar) -- stale the moment a first reply appeared, so pressing play a second time inserted a duplicate reply DOM node alongside the original instead of replacing it."
    i = nb.index(c.id)
    nxt = nb.cells[i+1] if i+1 < len(nb.cells) else None
    if nxt is not None and nxt.ctype == 'assistant':
        # Clear the old reply now, synchronously, rather than letting _finalize_prompt_reply overwrite
        # it when the new one finishes -- otherwise a stale answer stays on screen for the whole run.
        nxt.source, nxt.details = '', None
        pend = pending_prompt_cell(c.id, oob_swap=f'outerHTML:#cell-{nxt.id}')
    else:
        # Positional OOB swaps (afterend/beforebegin/beforeend) insert only the tagged element's
        # *children* -- so pending_prompt_cell must be wrapped, not itself carry the hx-swap-oob attribute,
        # or its own id/hx-trigger="load" would be discarded on insertion. See _oob().
        pend = _oob(f'afterend:#cell-{c.id}', pending_prompt_cell(c.id))
    _start_prompt_run(c.id)
    return render_cell(c), pend

# %% ../nbs/05_cells.ipynb #623f0a3a
@rt
def run_prompt_poll(id:int) -> FT|str:
    "Poll a streaming Prompt reply -- returns the current partial text while still running (re-triggering itself), or finalizes into the real Assistant cell once done."
    global _prompt_state
    st = _prompt_state
    if st is None or st.cell_id != id:
        return ''  # stale poll (e.g. a second tab, or the reply was already finalized) -- nothing to do
    if not st.done:
        return pending_prompt_cell(id, ''.join(st.buffer))
    content, details = st.blocks
    _prompt_state = None
    c2 = _finalize_prompt_reply(id, content, details)
    return render_cell(c2) if c2 else ''

# %% ../nbs/05_cells.ipynb #47866bbf
def add_tool(fn:callable) -> callable:
    "Register `fn` as a tool the LLM can call on future Prompt-cell runs. Also usable as a decorator: `@add_tool`."
    if not callable(fn):
        raise TypeError(f'add_tool() expects a callable, got {fn!r}')
    if fn not in nb.tools:
        nb.tools.append(fn)
    return fn

# %% ../nbs/05_cells.ipynb #61480b90
_shell.push({'nb': nb, 'add_tool': add_tool})  # so code cells can call add_tool(...)/inspect nb directly, no import needed

def _push_tools() -> None:
    "Push every currently-selected tool function into the shared shell's namespace, keyed by name, so code the model suggests calling one of them (per tools_system_prompt(), see llms.py) is actually runnable as-is, no import needed. Called before each prompt run and after a kernel restart -- both leave the namespace out of sync with the current tool selection."
    tools = get_tool_list(nb.tool_selection) + nb.tools
    _shell.push({fn.__name__: fn for fn in tools})

_push_tools()  # populate the namespace once at startup, matching the current (default) tool selection

# %% ../nbs/05_cells.ipynb #ac17911d
def _output_text(blocks:list[dict]) -> str:
    "Flatten a code cell's output blocks (see Cell.output / run_code()) to plain text for the LLM context: stream/error/text-ish blocks pass through as-is, while binary display blocks (images etc.) become a short \"[<mime> output omitted]\" marker -- the model should at least know an output existed even though it can't be sent yet."
    texty = {None, 'text/plain', 'text/markdown', 'text/html', 'application/json'}
    return '\n'.join(b['data'] if b.get('mime') in texty else f"[{b['mime']} output omitted]" for b in blocks)

def llm_context(nb:Notebook, cur_id:int|None=None) -> str:
    "Exactly what a real model would receive: the visible cells up through `cur_id` (default: all), in order, with each code cell's outputs appended (via _output_text) so 'run this, then ask about the result' actually works. The `cur_id` cell itself is always included even if toggled invisible -- it's the question being asked, and dropping it would silently send a context with no prompt at the end."
    cutoff = len(nb.cells)
    cur = None
    if cur_id is not None:
        i = nb.index(cur_id)
        if i is not None: cutoff, cur = i + 1, nb.cells[i]
    lines = []
    for c in nb.cells[:cutoff]:
        if not (c.visible or c is cur): continue
        lines.append(f'[{c.ctype}] {c.source}')
        if c.output and isinstance(c.output, list):
            out = _output_text(c.output)
            if out: lines.append(f'[output] {out}')
    return '\n'.join(lines)

# %% ../nbs/05_cells.ipynb #44c07e09
def stub_reply(nb:Notebook, prompt:str) -> str:
    "Fake/placeholder LLM reply used when no model is available (lets you still test the GUI)."
    n = sum(c.visible for c in nb.cells)
    # TODO: use the prompt_llm routine instead to get real llm interaction
    return (f'(stub) I can see {n} visible cell(s). You said: '
            f'"{prompt.strip()}". Wire a real model into stub_reply() later.')


# %% ../nbs/05_cells.ipynb #db01327f
def _default_picks(force:bool=False) -> None:
    "Choose the standard/reasoning models from nb.models: the first model matching _PREFERRED_MODEL_SUBSTR (else the first model at all), and the first advertising Ollama's 'thinking' capability (else none). By default only *fills in* a pick that isn't valid any more -- None, or naming a model that has since disappeared -- so re-listing the models (see refresh_models(), which runs on every brain-menu hover) can't quietly overwrite a choice the user made. `force` re-derives both regardless, which is what a fresh start wants (see ensure_models())."
    ids = {m['id'] for m in nb.models}
    if force or nb.standard_model not in ids:
        preferred = next((m for m in nb.models if _PREFERRED_MODEL_SUBSTR in m['id']), None)
        nb.standard_model = preferred['id'] if preferred else (nb.models[0]['id'] if nb.models else None)
    if force or nb.reasoning_model not in ids:
        reasoning = next((m for m in nb.models if 'thinking' in m.get('capabilities', [])), None)
        nb.reasoning_model = reasoning['id'] if reasoning else None

def ensure_models() -> None:
    "Populate nb.models (info dicts, see get_model_list()) plus default picks for both models, tolerating an unreachable local LLM server. Run once at startup; refresh_models() takes over from there, so an Ollama that wasn't running yet when boopiter started is picked up on the next brain-menu hover rather than needing a server restart."
    try:
        nb.models = get_model_list()
    except Exception:
        nb.models = []
    _default_picks(force=True)
    _apply_active_model()  # sweep out anything a previous boopiter process (or another Ollama client) left resident, so the memory state matches the picks the menu is about to show

# %% ../nbs/05_cells.ipynb #3014974b
try:
    @app.on_event('startup')
    def _load_models() -> None:
        "Fetch the local model list once, when the real server actually starts up."
        ensure_models()
        start_plugins()  # spawn each registered plugin's background task (e.g. SystemMonitor's sampler) -- only on a real boot, never during import/tests
except:
    print("WARNING: Can't test this cell in notebook, no app")

