# %% ../nbs/05_cells.ipynb #6560e13e
_CAPABILITY_EMOJI = {'vision': '👁️', 'tools': '🔧', 'thinking': '🧠'}  # capability (from get_ollama_list()'s 'capabilities') -> emoji shown after a model's name in dropdowns; capabilities we don't care about (completion -- basically universal, insert, embedding, ...) are silently ignored, and a model with none of these three gets no emoji at all

# %% ../nbs/05_cells.ipynb #745c1ce6
def _model_label(m:dict) -> str:
    "A model's dropdown label: its bare name, plus a trailing run of capability emojis (see _CAPABILITY_EMOJI) if it has any worth flagging."
    emoji = ''.join(_CAPABILITY_EMOJI[c] for c in m.get('capabilities', []) if c in _CAPABILITY_EMOJI)
    return f"{m['model']}  {emoji}" if emoji else m['model']

# %% ../nbs/05_cells.ipynb #80b17b22
def _model_select(models:list[dict], active_id:str|None, route) -> FT:
    "An inline, DOM-contained list of `models` as clickable rows -- NOT a native <select>, whose option list the browser renders as OS chrome *outside* the page DOM, which breaks brain_menu()'s hover/focus-within visibility the moment the pointer moves onto it (the whole menu vanishes before you can pick anything). Clicking a row posts the chosen model id to `route`, which re-renders the whole brain menu (hx_target=#brain-menu) so the new pick's checkmark shows. Shared by the Standard/Reasoning pickers. While Ollama is unreachable (nb.ollama_ok False, see refresh_models()) its models are greyed and made unclickable rather than dropped from the list: a model that can't answer right now shouldn't look selectable, but silently removing entries would also throw away a pick you'd made -- over something as ordinary as a restart or a network hiccup -- and dead-drop models, which don't need Ollama at all, stay live alongside them."
    rows = []
    for m in models:
        active = (m['id'] == active_id)
        dead = not nb.ollama_ok and m['id'].startswith(OLLAMA_PREFIX)
        label = [Span('✓' if active else '', cls='inline-block w-3 text-cyan-400'), Span(_model_label(m))]
        cls = 'flex items-center gap-1 py-0.5' + (' font-semibold' if active else '') + (' opacity-40' if dead else '')
        # A greyed row is rendered without its hx_post, so a click is inert -- 'disabled' isn't a
        # thing on an <a>, and leaving the post wired up would let you select a model that can't answer.
        link = fh.A(*label, cls=cls, title='Ollama unreachable') if dead else fh.A(
            *label, hx_post=route.to(model=m['id']), hx_target='#brain-menu', hx_swap='outerHTML', cls=cls)
        rows.append(fh.Li(link))
    return fh.Ul(*rows, cls='menu menu-sm p-0 gap-0 w-full max-h-64 overflow-y-auto flex-nowrap')

# %% ../nbs/05_cells.ipynb #9e3ec772
def _dropdown_width_px(models:list[dict]) -> int:
    "Estimate a comfortable width (px) for brain_menu()'s popup from the longest model label (name + capability emojis) among `models` -- a fixed width clipped the select boxes (arrow overlapping the text) whenever a name+emoji combo ran longer than expected, applied via inline style (see brain_menu()) since a computed w-[Npx] class never works against this app's precompiled static tailwind.css. ~9px/char is a rough per-character width at this font size; the +100 covers the select's own padding/border/dropdown-arrow chrome plus the popup's own outer p-2 padding. Clamped to a sane range either way."
    longest = max((len(_model_label(m)) for m in models), default=20)
    return max(220, min(380, 45 + longest * 8))

# %% ../nbs/05_cells.ipynb #fada779f
_EFFORT_LEVELS = ('l', 'm', 'h')

def brain_menu(icon_cls:str) -> FT:
    "Hover menu (styled like tools_menu) for picking the Standard and Reasoning models, SolveIt-style -- the Reasoning picker only lists models advertising Ollama's 'thinking' capability (see get_ollama_list()/ensure_models()), with an L/M/H effort control alongside it (passed through as Chat(...)(think=...) -- see stream_llm_reply()). The brain icon itself doubles as a toggle: click it to switch whether the reasoning or standard model actually answers Prompt cells (nb.use_reasoning/active_model()) -- its SVG strokes turn cyan (matching the 'Tricky...' streaming indicator's color, our existing 'this is thinking' cue) while on. Re-renders itself wholesale on toggle (hx_target=self) since the button's own color has to change along with the menu."
    reasoning_models = [m for m in nb.models if 'thinking' in m.get('capabilities', [])]
    # DaisyUI's .menu auto-flexes a li's direct children into a row -- explicit flex-col here
    # overrides that so Standard/Reasoning/Effort stack vertically instead of piling up sideways.
    rows = [Div('Model Selection', cls='font-bold text-sm mb-1'),
            # Sits up here, under the header and above both pickers, rather than down by Effort:
            # it applies to whichever model answers, not just the reasoning one, and the Effort row
            # it used to follow only renders at all when a thinking-capable model exists.
            Div(Span('Keep loaded', cls='text-xs font-semibold mr-2'), _keep_alive_control(),
                Span('min', cls='text-xs ml-1 opacity-60'), cls='flex items-center'),
            _num_ctx_control(),
            Div('Standard model', cls='text-sm mt-2'),
            _model_select(nb.models, nb.standard_model, set_standard_model) if nb.models else Span('no models', cls='text-xs opacity-50'),
            Div('Reasoning model', cls='text-sm mt-2 text-cyan-400'),  # cyan reinforces the same 'this is thinking' cue as the brain icon's own toggled color and the 'Tricky...' streaming indicator
            _model_select(reasoning_models, nb.reasoning_model, set_reasoning_model) if reasoning_models else Span('none available', cls='text-xs opacity-50')]
    if reasoning_models:
        rows.append(Div(
            Span('Effort', cls='text-xs font-semibold mr-2'),
            *[Label(Input(type='radio', name='effort', checked=(nb.reasoning_effort == lvl), cls='radio radio-xs',
                          hx_post=set_reasoning_effort.to(effort=lvl), hx_swap='none'),
                    Span(lvl.upper(), cls='text-xs ml-1'), cls='flex items-center gap-1 mr-3 cursor-pointer')
              for lvl in _EFFORT_LEVELS],
            cls='flex items-center mt-2'))
    brain_cls = 'btn btn-ghost btn-circle btn-sm' + (' text-cyan-400' if nb.use_reasoning else '')
    width_px = _dropdown_width_px(nb.models)
    return Div(
        fh.Button(Icon('brain', cls=icon_cls), cls=brain_cls,
                  hx_post=toggle_reasoning, hx_target='#brain-menu', hx_swap='outerHTML'),
        # width is estimated from the longest model label (see _dropdown_width_px) rather than
        # fixed, so a long name+emoji combo doesn't overflow its select box -- set via inline style,
        # NOT a w-[Npx] utility class: this app serves a precompiled static tailwind.css (see
        # _tw_header()) built by scanning literal class strings in the source, so a class built from
        # an f-string with a runtime-varying number never has a matching CSS rule and silently does
        # nothing. `left:50%; transform:translateX(-50%)` (centering -- DaisyUI's dropdown only
        # offers left/right anchoring, neither of which centers on the trigger) is inline for the
        # same reason.
        Ul(Li(Div(*rows, cls='flex flex-col gap-2 p-2')), tabindex='0',
           style=f'left:50%; transform:translateX(-50%); width:{width_px}px;',
           cls='dropdown-content menu bg-base-200 rounded-box z-10 p-1 shadow'),
        id='brain-menu', cls='dropdown dropdown-hover dropdown-bottom',
        # Re-list the models each time the pointer arrives, so an Ollama started after boopiter shows up
        # without a server restart (see refresh_models(), which answers 204 and swaps nothing when the
        # list is unchanged -- the usual case -- so this costs a hover nothing visually). The delay means
        # a pointer merely crossing the icon on its way elsewhere never fires the request.
        hx_get=refresh_models, hx_trigger='mouseenter delay:150ms', hx_target='#brain-menu', hx_swap='outerHTML')


# %% ../nbs/05_cells.ipynb #7f7b8257
def _apply_active_model() -> None:
    "After any brain-menu change (standard_model/reasoning_model/use_reasoning), drop every Ollama model that isn't one of the two current picks -- see sync_ollama_loaded(), which does the sweep -- so switching models frees the old one's RAM/VRAM instead of leaving a stack of resident weights behind. Both picks are kept, not just nb.active_model(), because flipping the reasoning toggle back and forth is a common move and shouldn't mean reloading from disk each time. Runs on a daemon thread: unloading a large model can take a beat, and there's no reason to hold up the HTTP response (just the re-rendered menu) while Ollama frees memory."
    threading.Thread(target=sync_ollama_loaded, args=([nb.standard_model, nb.reasoning_model],), daemon=True).start()

# %% ../nbs/05_cells.ipynb #bc2d594c
@rt
def set_standard_model(model:str) -> FT:
    "Change the Standard-model pick in the brain menu, then re-render the menu so the new pick's checkmark shows (see _model_select). Only affects Prompt answers directly if the reasoning toggle is currently off -- see nb.active_model()."
    if any(m['id'] == model for m in nb.models) and model != nb.standard_model:
        nb.standard_model = model
        _apply_active_model()
    return brain_menu(_TOPBAR_ICON_CLS_LG)

# %% ../nbs/05_cells.ipynb #ee97c857
@rt
def set_reasoning_model(model:str) -> FT:
    "Change the Reasoning-model pick in the brain menu (restricted there to 'thinking'-capable models), then re-render the menu so the new pick's checkmark shows (see _model_select). Only affects Prompt answers directly if the reasoning toggle is currently on -- see nb.active_model()."
    if any(m['id'] == model for m in nb.models) and model != nb.reasoning_model:
        nb.reasoning_model = model
        _apply_active_model()
    return brain_menu(_TOPBAR_ICON_CLS_LG)

# %% ../nbs/05_cells.ipynb #cee2215a
@rt
def toggle_reasoning() -> FT:
    "The brain-icon click: flip whether the reasoning or standard model answers Prompt cells. Returns the whole re-rendered brain_menu(), since the button itself needs to pick up its new highlighted state."
    nb.use_reasoning = not nb.use_reasoning
    _apply_active_model()
    return brain_menu(_TOPBAR_ICON_CLS_LG)

# %% ../nbs/05_cells.ipynb #refreshmodels1
@rt
def refresh_models():
    "Re-list the available models and re-render the brain menu if anything actually changed -- wired to mouseenter on the menu itself (see brain_menu()), so starting Ollama *after* boopiter no longer means restarting the server to see its models; hovering the brain icon is enough. Returns 204 No Content whenever nothing changed, which tells htmx to swap nothing at all: re-rendering an open dropdown on every hover would make the menu visibly flicker, and re-rendering it while the pointer is inside it risks disturbing the CSS :hover state keeping it open. Cheap enough to run on hover -- ~8ms for the /api/tags listing, with the expensive per-model capability probes served from cache (see _ollama_caps) -- and it runs alongside the CSS-driven dropdown rather than gating it, so the menu opens instantly either way. An unreachable Ollama does NOT clear the list (that's what strict=True distinguishes: 'Ollama is down' vs 'Ollama has no models'); it flips nb.ollama_ok so the existing entries render greyed and unclickable, keeping your current pick intact through a restart or a network hiccup. Picks are otherwise repaired, not reset (see _default_picks): a model that has genuinely vanished gets replaced, one you chose is left alone."
    try:
        models = get_model_list(strict=True)
    except Exception:
        if not nb.ollama_ok: return Response(status_code=204)  # already shown as unreachable -- nothing new to say
        nb.ollama_ok = False
        return brain_menu(_TOPBAR_ICON_CLS_LG)  # must re-render, or the greying would never appear
    was_down, nb.ollama_ok = not nb.ollama_ok, True
    if not was_down and [m['id'] for m in models] == [m['id'] for m in nb.models]:
        return Response(status_code=204)
    nb.models = models
    _default_picks()
    return brain_menu(_TOPBAR_ICON_CLS_LG)

# %% ../nbs/05_cells.ipynb #keepalivectrl1
def _keep_alive_control() -> FT:
    "The little number spinner beside the brain icon: how many minutes Ollama keeps a model in memory after it answers (nb.keep_alive_min, sent on every call -- see _chat_callkw). A native type=number input, so the browser supplies the up/down arrows for free; same widget shape as remsysmon's polling-interval control. 0 means unload the moment a reply finishes -- which is how you get to no resident models at all without quitting Ollama -- and -1 means keep it loaded indefinitely, for when you'd rather spend the RAM than wait on a reload. Only a backstop -- switching models in the brain menu already frees the old one immediately (see sync_ollama_loaded)."
    return Input(type='number', name='minutes', value=str(nb.keep_alive_min), min='-1', step='1',
                 title='Minutes Ollama keeps a model in memory after answering (0 = unload immediately, -1 = keep loaded indefinitely)',
                 hx_post=set_keep_alive, hx_trigger='change', hx_swap='none',
                 # Plain title= rather than DaisyUI's tooltip classes: this lives inside the
                 # hover-dropdown, and a tooltip popping out of an already-popped-out menu fights it.
                 cls='w-14 px-1 py-0.5 rounded bg-base-300 text-center tabular-nums text-xs '
                     'text-base-content border border-base-content/20')

@rt
def set_keep_alive(minutes:int=None) -> str:
    "Persist a new keep-alive from the spinner. Clamped at -1, the lowest value Ollama gives a distinct meaning: any negative keep_alive means 'keep this model loaded indefinitely', so -2 and -1 do the same thing and there's no reason to let the box go lower. Takes effect on the next model call; nothing to re-render, hence hx-swap=none."
    if minutes is not None: nb.keep_alive_min = max(-1, int(minutes))
    return ''

# %% ../nbs/05_cells.ipynb #shareui1
_share_state:dict|None = None  # the one in-flight (or last finished) share: {'status','url','error','name'}. Module-level like _run_state/_prompt_state, since a share is a single background job, not per-cell.
_SHARE_BUILD_WAIT = 240  # seconds to keep polling the published URL for GitHub Pages to build before giving up on it

def _share_bg(path:Path) -> None:
    "Background thread body: render + publish (see docsprocs.share_notebook), then wait for the page to actually go live before reporting success. The wait matters -- the push returns in a few seconds but Pages needs about a minute to build, so handing over the link the instant git finishes means the first click is a 404 that looks exactly like a failed share. Falls through to 'done' on timeout anyway rather than claiming failure: the build usually is coming, just slower than we waited. Catches everything, since quarto/gh/git can all fail and a traceback in a daemon thread would otherwise leave the notice spinning forever."
    import httpx, time as _t
    try:
        url = share_notebook(path)
        _share_state.update(status='building', url=url)
        deadline = _t.monotonic() + _SHARE_BUILD_WAIT
        while _t.monotonic() < deadline:
            try:
                if httpx.get(url, follow_redirects=True, timeout=10).status_code == 200: break
            except Exception: pass
            _t.sleep(3)
        _share_state.update(status='done')
    except Exception as e:
        _share_state.update(status='error', error=f'{type(e).__name__}: {e}')

def _share_toast(*kids, kind:str='alert-info', poll:bool=False) -> FT:
    "Wrap the share notice in the same #save-toast slot and DaisyUI alert the 'Saved' notice uses (see _toast), so it lands top-right where you already look for feedback. Unlike _toast it carries no self-clearing Script -- a share notice has to stay put long enough to copy the link out of it -- so it's dismissed by hand instead. `poll` re-requests it while the share is still running."
    kw = dict(hx_post=share_poll, hx_trigger='load delay:1500ms', hx_target='#share-toast', hx_swap='outerHTML') if poll else {}
    # Its own container, NOT the #save-toast slot: a share outlives any number of saves, and sharing
    # the slot meant hitting S mid-publish wiped the notice (and with it the link you were waiting for).
    # Offset below the save toast, via inline style since DaisyUI's toast-top pins both to the same edge.
    return Div(Div(*kids, cls=f'alert {kind} shadow-lg text-sm py-2 px-4 flex flex-col items-start gap-1'),
               id='share-toast', cls='toast toast-top toast-end z-50', style='top:4.5rem', **kw)

def share_panel() -> FT:
    "The share notice: progress while rendering and publishing, then the published URL with a button to copy it. Persistent -- it stays until dismissed, because its whole job is to leave the link on screen long enough to paste somewhere."
    st = _share_state or {}
    status = st.get('status')
    dismiss = fh.Button('Dismiss', cls='btn btn-xs btn-ghost',
                        hx_post=share_dismiss, hx_target='#share-toast', hx_swap='outerHTML')
    if status == 'done':
        url = st['url']
        return _share_toast(
            Div('Shared', cls='font-semibold'),
            fh.A(url, href=url, target='_blank', cls='link text-xs break-all max-w-xs'),
            Div(fh.Button('Copy link', cls='btn btn-xs btn-primary',
                          onclick=f'boopCopyText({json.dumps(url)})'), dismiss, cls='flex gap-2 mt-1'),
            kind='alert-success')
    if status == 'error':
        return _share_toast(Div('Share failed', cls='font-semibold'),
                            Div(st.get('error',''), cls='text-xs break-all max-w-xs opacity-80'), dismiss,
                            kind='alert-error')
    if status == 'building':
        return _share_toast(Div(Span(cls='loading loading-spinner loading-xs mr-2'),
                                Span('Waiting for GitHub Pages to build…'), cls='flex items-center'),
                            Div('Published; the link goes live shortly.', cls='text-xs opacity-70'),
                            poll=True)
    return _share_toast(Div(Span(cls='loading loading-spinner loading-xs mr-2'),
                            Span('Generating sharing site…'), cls='flex items-center'),
                        Div(st.get('name',''), cls='text-xs opacity-70'), poll=True)

@rt
def share_nb() -> FT:
    "Share the current notebook: save it to disk first (the published page should match what's on screen, and the render reads the file, not the in-memory cells), then render+publish on a background thread -- quarto alone takes several seconds, far too long to hold an HTTP response. Returns the notice immediately so the click visibly does something; it polls itself from there."
    global _share_state
    path = save_notebook()
    _share_state = {'status': 'working', 'name': path.name}
    threading.Thread(target=_share_bg, args=(path,), daemon=True).start()
    return share_panel()

@rt
def share_poll() -> FT:
    "Re-render the share notice while a share is running (see _share_toast's self-polling trigger)."
    return share_panel()

@rt
def share_dismiss() -> FT:
    "Close the share notice, emptying its slot. Doesn't cancel anything -- an in-flight publish finishes regardless; this only stops showing it."
    return Div(id='share-toast', cls='toast toast-top toast-end z-50', style='top:4.5rem')

# %% ../nbs/05_cells.ipynb #numctxctrl1
NUM_CTX_CHOICES = (8192, 16384, 32768, 65536, 262144)  # context windows offered in the brain menu. Roughly 360/710/1400/2850/11400 lines of notebook at ~23 tokens per 80-char line; the top entry is qwen3-vl:4b's own advertised maximum, kept as an escape hatch for a genuinely huge context even though it costs ~46GB of KV cache on that model.

def _num_ctx_control() -> FT:
    "The context-window row in the brain menu: NUM_CTX_CHOICES as radio buttons, labelled in K (8192 -> '8K') so five of them fit on one line. Same shape as the Effort row below, and deliberately not a native <select> -- see _model_select for why one can't live in this menu (the browser draws a real select's options as OS chrome outside the page, which collapses the hover menu the moment the pointer moves onto them). Applies to whichever model answers, so it sits up top beside Keep loaded rather than down among the reasoning-only controls. hx-swap=none, like Effort: the browser already shows the new selection, so there's nothing to re-render -- and re-rendering the menu under the pointer mid-hover is exactly what we avoid elsewhere. flex-wrap so the row breaks instead of overflowing when the popup is at its narrow end."
    return Div(Span('Context', cls='text-xs font-semibold mr-2'),
               *[Label(Input(type='radio', name='num_ctx', checked=(nb.num_ctx == n), cls='radio radio-xs',
                             hx_post=set_num_ctx.to(n=n), hx_swap='none'),
                       Span(f'{n // 1024}K', cls='text-xs ml-1'),
                       cls='flex items-center gap-1 mr-2 cursor-pointer')
                 for n in NUM_CTX_CHOICES],
               cls='flex items-center flex-wrap mt-2')

@rt
def set_num_ctx(n:int) -> str:
    "Pick a context window from the brain menu. Ignores anything not in NUM_CTX_CHOICES -- the value goes straight into an Ollama request, and there's no reason for this route to accept arbitrary sizes. Takes effect on the next model call; Ollama reloads the model whenever the requested window differs from the loaded one, which is also when the RAM actually changes."
    if n in NUM_CTX_CHOICES: nb.num_ctx = n
    return ''

